def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 99:
        return 'D'

    my_c = 0
    opp_c = 0
    for me, opp in history:
        if me == 'C':
            my_c += 1
        if opp == 'C':
            opp_c += 1
    my_d = n - my_c
    opp_d = n - opp_c

    last_me, last_opp = history[-1]

    if opp_d == 0:
        if my_d > 0:
            return 'D'
        if n >= 95:
            return 'D'
        if n >= 80 and rng.random() < 0.1:
            return 'D'
        return 'C'

    if opp_c == 0:
        return 'D'

    if last_opp == 'C':
        if my_d > opp_d + 3 and opp_c * 2 >= n:
            return 'D'
        return 'C'

    if n >= 2:
        prev_me, prev_opp = history[-2]
        if prev_me == 'D' and prev_opp == 'D':
            if opp_c * 2 >= n:
                return 'C'
        if prev_opp == 'C':
            if opp_c * 2 >= n:
                return 'C'

    if n >= 10:
        recent_opp = history[-10:]
        recent_c = 0
        for _, o in recent_opp:
            if o == 'C':
                recent_c += 1
        if recent_c >= 8 and rng.random() < 0.3:
            return 'C'

    return 'D'
